  ('29702122103386', 'سلوى حسن احمد جاب الله', '1120482540', '٥١ ش كمال فرج - محاولات - ترسا- الثلاثيني الجديد', 'تاريخ', '3706951', 'ليسانس اداب قسم تاريخ', 'حلوان', 2019, 'مقبول', 'بالأجر', '2025-09-21', 'دبلوم تربوي من كلية الدراسات العليا للتربية جامعة القاهرة', '1997-02-12', 'الجيزة', '21993065')
) AS t(national_id, name, phone, address, subject, teacher_code,
  qualification, university, grad_year, grade, contract_type, start_date,
  diploma, dob, gov, school_code)
LEFT JOIN base_schools bs ON bs.school_code = t.school_code::text
ON CONFLICT (national_id) DO UPDATE SET
  name = EXCLUDED.name,
  phone = EXCLUDED.phone,
  subject = EXCLUDED.subject,
  base_school_id = EXCLUDED.base_school_id,
  updated_at = NOW();

